/**
 * Individual payout list tab for AdminReferralPayouts
 *
 * Displays a paginated, filterable list of all referral payouts with
 * per-row process/cancel actions.
 */

import { useState, useEffect, useCallback, useMemo } from 'react';
import { useCedrosLoginAdminClientContext } from '../../hooks/useCedrosLoginAdminClientContext';
import { ApiClient, handleApiError } from '../../utils/apiClient';

// =============================================================================
// Types
// =============================================================================

interface AdminPayoutItem {
  id: string;
  referrerId: string;
  referrerEmail: string | null;
  referrerName: string | null;
  referredUserId: string;
  triggerType: string;
  amount: number;
  currency: string;
  status: string;
  txSignature: string | null;
  errorMessage: string | null;
  createdAt: string;
  completedAt: string | null;
}

interface ListPayoutsResponse {
  payouts: AdminPayoutItem[];
  total: number;
}

// =============================================================================
// Helpers
// =============================================================================

function formatAmount(amount: number, currency: string): string {
  if (currency.toUpperCase() === 'SOL') {
    const sol = amount / 1_000_000_000;
    return `${sol.toFixed(4)} SOL`;
  }
  return `${amount} ${currency}`;
}

function truncateAddress(address: string): string {
  if (address.length <= 16) return address;
  return `${address.slice(0, 8)}...${address.slice(-6)}`;
}

function formatDate(iso: string): string {
  return new Date(iso).toLocaleDateString(undefined, {
    month: 'short',
    day: 'numeric',
    year: 'numeric',
    hour: '2-digit',
    minute: '2-digit',
  });
}

const STATUS_OPTIONS = ['all', 'pending', 'completed', 'failed', 'cancelled'] as const;

// =============================================================================
// Component
// =============================================================================

/**
 * Paginated individual payout list with status filtering and per-row actions.
 *
 * Inputs: none.
 * Outputs: renders payout table with process/cancel buttons.
 * Errors: displayed inline.
 */
export function AdminPayoutList() {
  const { config, _internal } = useCedrosLoginAdminClientContext();

  const apiClient = useMemo(
    () =>
      new ApiClient({
        baseUrl: config.serverUrl,
        timeoutMs: config.requestTimeout,
        retryAttempts: config.retryAttempts,
        getAccessToken: _internal?.getAccessToken,
      }),
    [config.serverUrl, config.requestTimeout, config.retryAttempts, _internal]
  );

  const [statusFilter, setStatusFilter] = useState<string>('all');
  const [page, setPage] = useState(0);
  const pageSize = 20;

  const [data, setData] = useState<ListPayoutsResponse | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [fetchError, setFetchError] = useState<string | null>(null);
  const [actionMsg, setActionMsg] = useState<string | null>(null);
  const [busyId, setBusyId] = useState<string | null>(null);

  const fetchPayouts = useCallback(async () => {
    setIsLoading(true);
    setFetchError(null);
    try {
      const params = new URLSearchParams();
      if (statusFilter !== 'all') params.set('status', statusFilter);
      params.set('limit', String(pageSize));
      params.set('offset', String(page * pageSize));
      const response = await apiClient.get<ListPayoutsResponse>(
        `/admin/referral-payouts/list?${params.toString()}`
      );
      setData(response);
    } catch (err) {
      const error = handleApiError(err, 'Failed to load payouts');
      setFetchError(error.message);
    } finally {
      setIsLoading(false);
    }
  }, [apiClient, statusFilter, page]);

  useEffect(() => {
    fetchPayouts();
  }, [fetchPayouts]);

  const handleProcess = useCallback(
    async (id: string) => {
      setBusyId(id);
      setActionMsg(null);
      try {
        const result = await apiClient.post<{ txSignature: string }>(
          `/admin/referral-payouts/${id}/process`,
          {}
        );
        setActionMsg(`Processed: ${result.txSignature}`);
        fetchPayouts();
      } catch (err) {
        const error = handleApiError(err, 'Failed to process payout');
        setActionMsg(error.message);
      } finally {
        setBusyId(null);
      }
    },
    [apiClient, fetchPayouts]
  );

  const handleCancel = useCallback(
    async (id: string) => {
      setBusyId(id);
      setActionMsg(null);
      try {
        await apiClient.post(`/admin/referral-payouts/${id}/cancel`, {});
        setActionMsg('Payout cancelled.');
        fetchPayouts();
      } catch (err) {
        const error = handleApiError(err, 'Failed to cancel payout');
        setActionMsg(error.message);
      } finally {
        setBusyId(null);
      }
    },
    [apiClient, fetchPayouts]
  );

  const totalPages = data ? Math.ceil(data.total / pageSize) : 0;

  return (
    <>
      {/* Filter bar */}
      <div className="cedros-admin-referral-payouts__filter-bar">
        <label className="cedros-admin-referral-payouts__filter-label">
          Status:
          <select
            value={statusFilter}
            onChange={(e) => {
              setStatusFilter(e.target.value);
              setPage(0);
            }}
            className="cedros-admin-referral-payouts__filter-select"
          >
            {STATUS_OPTIONS.map((s) => (
              <option key={s} value={s}>
                {s.charAt(0).toUpperCase() + s.slice(1)}
              </option>
            ))}
          </select>
        </label>
        {data && (
          <span className="cedros-admin-referral-payouts__filter-count">
            {data.total} total
          </span>
        )}
      </div>

      {/* Action feedback */}
      {actionMsg && (
        <div className="cedros-admin-referral-payouts__result cedros-admin-referral-payouts__result--info">
          {actionMsg}
        </div>
      )}

      {/* Loading */}
      {isLoading && !data && (
        <div className="cedros-admin-referral-payouts--loading">
          <span className="cedros-admin-loading-indicator" />
          <span className="cedros-admin-loading-text">Loading payouts...</span>
        </div>
      )}

      {/* Error */}
      {fetchError && (
        <div className="cedros-admin-referral-payouts--error">
          <p className="cedros-admin-error">{fetchError}</p>
          <button
            type="button"
            className="cedros-button cedros-button-outline cedros-button-sm"
            onClick={fetchPayouts}
          >
            Retry
          </button>
        </div>
      )}

      {/* Table */}
      {data && data.payouts.length === 0 && (
        <div className="cedros-admin-empty-message">No payouts found.</div>
      )}

      {data && data.payouts.length > 0 && (
        <div className="cedros-admin-list-table" role="table" aria-label="All referral payouts">
          <div className="cedros-admin-list-thead" role="row">
            <div className="cedros-admin-list-th" role="columnheader">Date</div>
            <div className="cedros-admin-list-th" role="columnheader">Referrer</div>
            <div className="cedros-admin-list-th" role="columnheader">Trigger</div>
            <div className="cedros-admin-list-th" role="columnheader">Amount</div>
            <div className="cedros-admin-list-th" role="columnheader">Status</div>
            <div className="cedros-admin-list-th" role="columnheader">TX / Error</div>
            <div className="cedros-admin-list-th" role="columnheader">Actions</div>
          </div>
          {data.payouts.map((p) => (
            <div key={p.id} className="cedros-admin-list-row" role="row">
              <div className="cedros-admin-list-td" role="cell">
                {formatDate(p.createdAt)}
              </div>
              <div className="cedros-admin-list-td" role="cell">
                {p.referrerEmail || p.referrerName || truncateAddress(p.referrerId)}
              </div>
              <div className="cedros-admin-list-td" role="cell">
                {p.triggerType}
              </div>
              <div className="cedros-admin-list-td" role="cell">
                {formatAmount(p.amount, p.currency)}
              </div>
              <div className="cedros-admin-list-td" role="cell">
                <span className={`cedros-admin-referral-payouts__status cedros-admin-referral-payouts__status--${p.status}`}>
                  {p.status}
                </span>
              </div>
              <div className="cedros-admin-list-td cedros-admin-list-td-mono" role="cell">
                {p.txSignature && truncateAddress(p.txSignature)}
                {p.errorMessage && (
                  <span className="cedros-admin-list-td-muted" title={p.errorMessage}>
                    {p.errorMessage.slice(0, 40)}
                  </span>
                )}
              </div>
              <div className="cedros-admin-list-td" role="cell">
                {(p.status === 'pending' || p.status === 'failed') && (
                  <button
                    type="button"
                    className="cedros-button cedros-button-primary cedros-button-xs"
                    onClick={() => handleProcess(p.id)}
                    disabled={busyId !== null}
                  >
                    {busyId === p.id ? '...' : 'Process'}
                  </button>
                )}
                {p.status === 'pending' && (
                  <button
                    type="button"
                    className="cedros-button cedros-button-outline cedros-button-xs"
                    onClick={() => handleCancel(p.id)}
                    disabled={busyId !== null}
                    style={{ marginLeft: 4 }}
                  >
                    Cancel
                  </button>
                )}
              </div>
            </div>
          ))}
        </div>
      )}

      {/* Pagination */}
      {totalPages > 1 && (
        <div className="cedros-admin-referral-payouts__pagination">
          <button
            type="button"
            className="cedros-button cedros-button-outline cedros-button-xs"
            disabled={page === 0}
            onClick={() => setPage((p) => p - 1)}
          >
            Previous
          </button>
          <span className="cedros-admin-referral-payouts__page-info">
            Page {page + 1} of {totalPages}
          </span>
          <button
            type="button"
            className="cedros-button cedros-button-outline cedros-button-xs"
            disabled={page >= totalPages - 1}
            onClick={() => setPage((p) => p + 1)}
          >
            Next
          </button>
        </div>
      )}
    </>
  );
}
