/**
 * Admin referral payouts management component
 *
 * Tab 1: Summary — grouped-by-referrer view with Process All / Retry Failed
 * Tab 2: All Payouts — paginated individual list with per-row actions
 *
 * Requires system admin privileges.
 */

import { useState, useEffect, useCallback, useMemo } from 'react';
import { useCedrosLoginAdminClientContext } from '../../hooks/useCedrosLoginAdminClientContext';
import { ApiClient, handleApiError } from '../../utils/apiClient';
import { AdminPayoutList } from './AdminPayoutList';

// =============================================================================
// Types
// =============================================================================

interface ReferrerPayout {
  referrerId: string;
  payoutWalletAddress: string | null;
  totalPendingAmount: number;
  pendingCount: number;
  currency: string;
}

interface ReferralPayoutsResponse {
  referrers: ReferrerPayout[];
  total: number;
}

interface ProcessPayoutsResponse {
  processed: number;
  failed: number;
  totalAmount: number;
  skippedNoWallet: number;
}

interface RetryFailedResponse {
  resetCount: number;
}

// =============================================================================
// Helpers
// =============================================================================

function formatAmount(amount: number, currency: string): string {
  if (currency.toUpperCase() === 'SOL') {
    const sol = amount / 1_000_000_000;
    return `${sol.toFixed(4)} SOL`;
  }
  return `${amount} ${currency}`;
}

function truncateAddress(address: string): string {
  if (address.length <= 16) return address;
  return `${address.slice(0, 8)}...${address.slice(-6)}`;
}

type TabId = 'summary' | 'all';

// =============================================================================
// Props
// =============================================================================

export interface AdminReferralPayoutsProps {
  className?: string;
}

// =============================================================================
// Component
// =============================================================================

/**
 * Admin UI for managing direct referral payouts.
 *
 * Inputs: none beyond className.
 * Outputs: renders tabbed payout management UI.
 * Errors: displayed inline with retry options.
 */
export function AdminReferralPayouts({ className = '' }: AdminReferralPayoutsProps) {
  const [activeTab, setActiveTab] = useState<TabId>('summary');

  return (
    <div className={`cedros-admin-referral-payouts ${className}`}>
      <div className="cedros-admin-referral-payouts__tabs">
        <button
          type="button"
          className={`cedros-admin-referral-payouts__tab ${activeTab === 'summary' ? 'cedros-admin-referral-payouts__tab--active' : ''}`}
          onClick={() => setActiveTab('summary')}
        >
          Summary
        </button>
        <button
          type="button"
          className={`cedros-admin-referral-payouts__tab ${activeTab === 'all' ? 'cedros-admin-referral-payouts__tab--active' : ''}`}
          onClick={() => setActiveTab('all')}
        >
          All Payouts
        </button>
      </div>

      {activeTab === 'summary' ? <SummaryTab /> : <AdminPayoutList />}
    </div>
  );
}

// =============================================================================
// Summary Tab
// =============================================================================

function SummaryTab() {
  const { config, _internal } = useCedrosLoginAdminClientContext();

  const apiClient = useMemo(
    () =>
      new ApiClient({
        baseUrl: config.serverUrl,
        timeoutMs: config.requestTimeout,
        retryAttempts: config.retryAttempts,
        getAccessToken: _internal?.getAccessToken,
      }),
    [config.serverUrl, config.requestTimeout, config.retryAttempts, _internal]
  );

  const [data, setData] = useState<ReferralPayoutsResponse | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [fetchError, setFetchError] = useState<string | null>(null);

  const [isProcessing, setIsProcessing] = useState(false);
  const [processResult, setProcessResult] = useState<ProcessPayoutsResponse | null>(null);
  const [processError, setProcessError] = useState<string | null>(null);

  const [isRetrying, setIsRetrying] = useState(false);
  const [retryResult, setRetryResult] = useState<RetryFailedResponse | null>(null);
  const [retryError, setRetryError] = useState<string | null>(null);

  const [autoEnabled, setAutoEnabled] = useState<boolean | null>(null);

  const fetchPayouts = useCallback(async () => {
    setIsLoading(true);
    setFetchError(null);
    try {
      const response = await apiClient.get<ReferralPayoutsResponse>('/admin/referral-payouts');
      setData(response);
    } catch (err) {
      const error = handleApiError(err, 'Failed to load referral payouts');
      setFetchError(error.message);
    } finally {
      setIsLoading(false);
    }
  }, [apiClient]);

  const fetchAutoStatus = useCallback(async () => {
    try {
      const settings = await apiClient.get<Record<string, { value: string }>>('/admin/settings');
      const val = settings?.['payout_auto_enabled']?.value;
      setAutoEnabled(val === 'true');
    } catch {
      // Non-critical
    }
  }, [apiClient]);

  useEffect(() => {
    fetchPayouts();
    fetchAutoStatus();
  }, [fetchPayouts, fetchAutoStatus]);

  const handleProcessAll = useCallback(async () => {
    setIsProcessing(true);
    setProcessResult(null);
    setProcessError(null);
    try {
      const result = await apiClient.post<ProcessPayoutsResponse>(
        '/admin/referral-payouts/process',
        {}
      );
      setProcessResult(result);
      fetchPayouts();
    } catch (err) {
      const error = handleApiError(err, 'Failed to process payouts');
      setProcessError(error.message);
    } finally {
      setIsProcessing(false);
    }
  }, [apiClient, fetchPayouts]);

  const handleRetryFailed = useCallback(async () => {
    setIsRetrying(true);
    setRetryResult(null);
    setRetryError(null);
    try {
      const result = await apiClient.post<RetryFailedResponse>(
        '/admin/referral-payouts/retry-failed',
        {}
      );
      setRetryResult(result);
      fetchPayouts();
    } catch (err) {
      const error = handleApiError(err, 'Failed to retry failed payouts');
      setRetryError(error.message);
    } finally {
      setIsRetrying(false);
    }
  }, [apiClient, fetchPayouts]);

  const actionBusy = isProcessing || isRetrying;

  if (isLoading && !data) {
    return (
      <div className="cedros-admin-referral-payouts cedros-admin-referral-payouts--loading">
        <span className="cedros-admin-loading-indicator" />
        <span className="cedros-admin-loading-text">Loading referral payouts...</span>
      </div>
    );
  }

  if (fetchError) {
    return (
      <div className="cedros-admin-referral-payouts cedros-admin-referral-payouts--error">
        <p className="cedros-admin-error">{fetchError}</p>
        <button
          type="button"
          className="cedros-button cedros-button-outline cedros-button-sm"
          onClick={fetchPayouts}
        >
          Retry
        </button>
      </div>
    );
  }

  const referrers = data?.referrers ?? [];
  const totalPending = data?.total ?? 0;
  const summaryCurrency = referrers[0]?.currency ?? 'SOL';
  const summaryTotalAmount = referrers.reduce((acc, r) => acc + r.totalPendingAmount, 0);

  return (
    <>
      <div className="cedros-admin-referral-payouts__header">
        <div className="cedros-admin-referral-payouts__summary">
          <div className="cedros-admin-stat-card">
            <span className="cedros-admin-stat-label">Pending Referrers</span>
            <span className="cedros-admin-stat-value">{totalPending}</span>
          </div>
          {totalPending > 0 && (
            <div className="cedros-admin-stat-card">
              <span className="cedros-admin-stat-label">Total Pending Amount</span>
              <span className="cedros-admin-stat-value">
                {formatAmount(summaryTotalAmount, summaryCurrency)}
              </span>
            </div>
          )}
          {autoEnabled !== null && (
            <div className="cedros-admin-stat-card">
              <span className="cedros-admin-stat-label">Auto-Processing</span>
              <span className="cedros-admin-stat-value">
                {autoEnabled ? 'ON' : 'OFF'}
              </span>
            </div>
          )}
        </div>

        <div className="cedros-admin-referral-payouts__actions">
          <button
            type="button"
            className="cedros-button cedros-button-primary cedros-button-sm"
            onClick={handleProcessAll}
            disabled={actionBusy || totalPending === 0}
            aria-busy={isProcessing}
          >
            {isProcessing ? 'Processing...' : 'Process All Payouts'}
          </button>
          <button
            type="button"
            className="cedros-button cedros-button-outline cedros-button-sm"
            onClick={handleRetryFailed}
            disabled={actionBusy}
            aria-busy={isRetrying}
          >
            {isRetrying ? 'Retrying...' : 'Retry Failed'}
          </button>
        </div>
      </div>

      {processResult && (
        <div className="cedros-admin-referral-payouts__result cedros-admin-referral-payouts__result--success">
          Processed {processResult.processed} payout(s) totalling{' '}
          {formatAmount(processResult.totalAmount, summaryCurrency)}.
          {processResult.failed > 0 && ` ${processResult.failed} failed.`}
          {processResult.skippedNoWallet > 0 &&
            ` ${processResult.skippedNoWallet} skipped (no wallet).`}
        </div>
      )}
      {processError && (
        <div className="cedros-admin-referral-payouts__result cedros-admin-referral-payouts__result--error">
          {processError}
        </div>
      )}
      {retryResult && (
        <div className="cedros-admin-referral-payouts__result cedros-admin-referral-payouts__result--success">
          Reset {retryResult.resetCount} failed payout(s) for retry.
        </div>
      )}
      {retryError && (
        <div className="cedros-admin-referral-payouts__result cedros-admin-referral-payouts__result--error">
          {retryError}
        </div>
      )}

      {referrers.length === 0 ? (
        <div className="cedros-admin-empty-message">No pending referral payouts.</div>
      ) : (
        <div className="cedros-admin-list-table" role="table" aria-label="Pending referral payouts">
          <div className="cedros-admin-list-thead" role="row">
            <div className="cedros-admin-list-th" role="columnheader">Referrer ID</div>
            <div className="cedros-admin-list-th" role="columnheader">Wallet Address</div>
            <div className="cedros-admin-list-th" role="columnheader">Pending Referrals</div>
            <div className="cedros-admin-list-th" role="columnheader">Total Amount</div>
          </div>
          {referrers.map((referrer) => (
            <div key={referrer.referrerId} className="cedros-admin-list-row" role="row">
              <div className="cedros-admin-list-td cedros-admin-list-td-mono" role="cell">
                <button
                  type="button"
                  className="cedros-admin-user-uuid-link"
                  onClick={() => navigator.clipboard?.writeText(referrer.referrerId)}
                  title={`Click to copy: ${referrer.referrerId}`}
                >
                  {truncateAddress(referrer.referrerId)}
                </button>
              </div>
              <div className="cedros-admin-list-td" role="cell">
                {referrer.payoutWalletAddress ? (
                  <button
                    type="button"
                    className="cedros-admin-user-uuid-link cedros-admin-list-td-mono"
                    onClick={() =>
                      navigator.clipboard?.writeText(referrer.payoutWalletAddress!)
                    }
                    title={`Click to copy: ${referrer.payoutWalletAddress}`}
                  >
                    {truncateAddress(referrer.payoutWalletAddress)}
                  </button>
                ) : (
                  <span className="cedros-admin-list-td-muted">No wallet</span>
                )}
              </div>
              <div className="cedros-admin-list-td" role="cell">
                {referrer.pendingCount}
              </div>
              <div className="cedros-admin-list-td" role="cell">
                {formatAmount(referrer.totalPendingAmount, referrer.currency)}
              </div>
            </div>
          ))}
        </div>
      )}
    </>
  );
}
